#!/usr/bin/env bun
// Writes unit-plan-gate.ts beside this file: the State Version gate and the
// Unit plan reader a 2.11.0 to 2.11.4 AI-DLC runs when it opens a piece of
// work, taken from `git show v2.11.0:core/tools/aidlc-lib.ts` with two changes:
// comment-only lines are left out, and each character outside printable ASCII
// on a code line is written as its \u escape, so the copy is plain ASCII and
// every string means the same at run time. The gate's message names the
// release's entry command, which lives in another file of that release: it is
// the one stub, above the copied lines. Run it by hand in a clone that has the
// release tags:
//
//   bun tests/fixtures/unit-plan-gate-2.11.0/generate.ts
//   bun tests/fixtures/unit-plan-gate-2.11.0/generate.ts --hashes v2.11.0 v2.11.4
//
// The second form prints, per tag, the hash of each function the test pins.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { join } from "node:path";

const TAG = "v2.11.0";
// In the order the copy needs them: the gate, then the reader and what it calls.
const DECLARATIONS = [
  "CURRENT_STATE_VERSION",
  "StateVersionClassification",
  "classifyStateVersion",
  "UNIT_NAME_REGEX",
  "UNIT_NAME_MAX_LENGTH",
  "validateUnitName",
  "errorMessage",
  "UNIT_KINDS",
  "UnitKind",
  "UnitDependencyEdge",
  "BoltDagParse",
  "extractYamlUnitsBlock",
  "unquoteScalar",
  "parseInlineDepsList",
  "parseUnitsBlock",
  "computeBatches",
  "parseBoltDag",
  "unitsBlockRepair",
];
export const PINNED_FUNCTIONS = ["classifyStateVersion", "parseBoltDag", "parseUnitsBlock"];
export const MARKER = "// ---- copied from v2.11.0 below this line ----";
const STUB = 'const entrySkillInvocation = (): string => "/aidlc";';

function show(tag: string, path: string): string {
  const shown = spawnSync("git", ["show", `${tag}:${path}`], { encoding: "utf-8", maxBuffer: 64 * 1024 * 1024 });
  if (shown.status !== 0) throw new Error(`git show ${tag}:${path}: ${shown.stderr}`);
  return shown.stdout.replace(/\r\n/g, "\n");
}

const COMMENT_ONLY = /^\s*(?:\/\/|\/\*|\*)/;
const BACKSLASH = String.fromCharCode(92);

function plain(text: string): string {
  return text
    .split("\n")
    .filter((line) => !COMMENT_ONLY.test(line))
    .map((line) =>
      [...line]
        .map((char) => {
          const code = char.codePointAt(0) ?? 0;
          return code > 0x7e ? `${BACKSLASH}u${code.toString(16).padStart(4, "0")}` : char;
        })
        .join("")
    )
    .join("\n");
}

/**
 * A top-level declaration of `name`: a function, const or interface from its
 * first line through the first line that is exactly `}` or `};` (or the line
 * itself when it ends with `;`), and a type through the first line ending `;`.
 */
export function declaration(text: string, name: string): string {
  const start = new RegExp(`^(?:export )?(?:function ${name}\\(|const ${name}\\b|interface ${name}\\b|type ${name}\\b)`, "m").exec(text);
  if (!start) throw new Error(`no top-level ${name}`);
  const line = text.slice(start.index, text.indexOf("\n", start.index));
  if (line.endsWith(";")) return line;
  const close = /\btype /.test(start[0]) ? /;\n/g : /\n\};?\n/g;
  close.lastIndex = start.index;
  const end = close.exec(text);
  if (!end) throw new Error(`${name} has no closing line`);
  return text.slice(start.index, end.index + end[0].length - 1);
}

export function hash(text: string): string {
  return createHash("sha256").update(text).digest("hex");
}

const copiedForm = (text: string): string => plain(text).replace(/\n{3,}/g, "\n\n");

function copied(tag: string): string {
  const lib = show(tag, "core/tools/aidlc-lib.ts");
  return copiedForm(DECLARATIONS.map((name) => declaration(lib, name)).join("\n\n")).trimEnd();
}

const HEADER = [
  "// Generated by generate.ts beside this file; do not edit by hand.",
  "// The State Version gate and the Unit plan reader of AI-DLC 2.11.0, as a",
  "// 2.11.0 to 2.11.4 AI-DLC runs them when it opens a piece of work: the gate",
  "// first, the reader past it. core/tools/aidlc-lib.ts classifyStateVersion,",
  "// parseBoltDag, unitsBlockRepair and what they call, with comment-only lines",
  "// left out and characters outside printable ASCII written as escapes. The",
  "// one stub is the release's entry command, which the gate's message names.",
  STUB,
].join("\n");

if (import.meta.main) {
  const args = process.argv.slice(2);
  if (args[0] === "--hashes") {
    // Only the pinned functions, from whichever file a later release keeps
    // each in: 2.11.4 moved the Unit plan reader to aidlc-unit-dag.ts.
    for (const tag of args.slice(1)) {
      const files = ["core/tools/aidlc-lib.ts", "core/tools/aidlc-unit-dag.ts"].flatMap((path) => {
        try {
          return [show(tag, path)];
        } catch {
          return []; // No such file at this tag.
        }
      });
      const found = (name: string): string => {
        for (const text of files) {
          try {
            return declaration(text, name);
          } catch {
            // Not in this file at this tag.
          }
        }
        throw new Error(`no top-level ${name} at ${tag}`);
      };
      console.log(`${tag}\t${PINNED_FUNCTIONS.map((name) => `${name}=${hash(declaration(`${copiedForm(found(name))}\n`, name))}`).join("\t")}`);
    }
  } else {
    const body = copied(TAG);
    writeFileSync(join(import.meta.dir, "unit-plan-gate.ts"), `${HEADER}\n${MARKER}\n${body}\n`);
    console.log(`wrote unit-plan-gate.ts from ${TAG}; body sha256 ${hash(`${body}\n`)}`);
  }
}
